#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

class Hungarian {
public:
    static const int SIZE = 2000;
    int cnt, pos[SIZE], rev[SIZE];
    int gao(int n, vector<int> e[]) {
        cnt = 0;
        memset(pos, -1, sizeof(pos));
        memset(rev, -1, sizeof(rev));
        for (int i = 0; i < n; i++) {
            memset(v, 0, sizeof(v));
            if (match(i, e)) cnt++;
        }
        return cnt;
    }
private:
    int v[SIZE];
    bool match(int x, vector<int> e[]) {
        for (int y : e[x]) {
            if (!v[y]) {
                v[y] = 1;
                if (rev[y] < 0 || match(rev[y], e)) {
                    pos[x] = y;
                    rev[y] = x;
                    return true;
                }
            }
        }
        return false;
    }
};

const int INF = 1000000000;
const int dr[] = {0, -1, 0, 1};
const int dc[] = {1, 0, -1, 0};
int a[12][12], b[12][12], f[12][12], n, t;
vector<int> e[2000], c[12][12];

void floodfill(int sr, int sc) {
    queue<int> qr, qc;
    memset(f, -1, sizeof(f));
    qr.push(sr);
    qc.push(sc);
    f[sr][sc] = 0;
    while (!qr.empty()) {
        int r = qr.front(); qr.pop();
        int c_ = qc.front(); qc.pop();
        for (int i = 0; i < 4; i++) {
            int tr = r + dr[i], tc = c_ + dc[i];
            if (a[tr][tc] >= 0 && f[tr][tc] < 0) {
                f[tr][tc] = f[r][c_] + 1;
                qr.push(tr);
                qc.push(tc);
            }
        }
    }
}

void setmark(int sr, int sc, int cnt) {
    int v[12][12];
    queue<int> qr, qc;
    memset(v, -1, sizeof(v));
    qr.push(sr);
    qc.push(sc);
    v[sr][sc] = 0;
    while (!qr.empty()) {
        int r = qr.front(); qr.pop();
        int c_ = qc.front(); qc.pop();
        if (v[r][c_] > min(t, f[r][c_])) continue;
        for (int j : c[r][c_]) {
            for (int i = 0; i < cnt; i++) e[n + i].push_back(j);
        }
        if (v[r][c_] == min(t, f[r][c_])) continue;
        for (int i = 0; i < 4; i++) {
            int tr = r + dr[i], tc = c_ + dc[i];
            if (a[tr][tc] >= 0 && v[tr][tc] < 0) {
                v[tr][tc] = v[r][c_] + 1;
                qr.push(tr);
                qc.push(tc);
            }
        }
    }
    n += cnt;
}

int main() {
    int m = 0, o = 0, sr, sc;
    cin >> n >> t;
    memset(a, -1, sizeof(a));
    memset(b, -1, sizeof(b));
    for (int i = 1; i <= n; i++) {
        string line;
        getline(cin, line);
        for (int j = 1; j <= n; j++) {
            char ch = line[j - 1];
            if (ch >= '0' && ch <= '9') a[i][j] = ch - '0';
            if (ch == 'Z') {
                sr = i;
                sc = j;
            }
        }
    }
    floodfill(sr, sc);
    for (int i = 1; i <= n; i++) {
        string line;
        getline(cin, line);
        for (int j = 1; j <= n; j++) {
            char ch = line[j - 1];
            if (ch >= '0' && ch <= '9') b[i][j] = ch - '0';
            for (int k = 0; k < b[i][j]; k++) c[i][j].push_back(o++);
        }
    }
    for (int i = 1; i <= n; i++) for (int j = 1; j <= n; j++) if (f[i][j] < 0) f[i][j] = INF;
    for (int i = 1; i <= n; i++) for (int j = 1; j <= n; j++) if (a[i][j] > 0) setmark(i, j, a[i][j]);
    Hungarian match;
    cout << match.gao(m, e) << "\n";
    return 0;
}
